package com.seamless.player;
import android.app.*;import android.appwidget.*;import android.content.*;import android.widget.RemoteViews;
public class PlayerWidget extends AppWidgetProvider {
 @Override public void onUpdate(Context c,AppWidgetManager m,int[] ids){for(int id:ids)update(c,m,id);}
 static void update(Context c,AppWidgetManager m,int id){RemoteViews v=new RemoteViews(c.getPackageName(),com.seamless.player.R.layout.widget);v.setOnClickPendingIntent(R.id.widget_play,PendingIntent.getBroadcast(c,1,new Intent(c,PlayerWidget.class).setAction("com.seamless.player.PLAY_PAUSE"),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE));v.setOnClickPendingIntent(R.id.widget_next,PendingIntent.getBroadcast(c,2,new Intent(c,PlayerWidget.class).setAction("com.seamless.player.NEXT"),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE));Intent open=new Intent(c,MainActivity.class);v.setOnClickPendingIntent(R.id.widget_title,PendingIntent.getActivity(c,3,open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE));m.updateAppWidget(id,v);}
 @Override public void onReceive(Context c,Intent i){super.onReceive(c,i);if("com.seamless.player.PLAY_PAUSE".equals(i.getAction())){if(MainActivity.player!=null){if(MainActivity.player.isPlaying())MainActivity.player.pause();else MainActivity.player.start();}}else if("com.seamless.player.NEXT".equals(i.getAction())){Intent open=new Intent(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);c.startActivity(open);}AppWidgetManager m=AppWidgetManager.getInstance(c);onUpdate(c,m,m.getAppWidgetIds(new ComponentName(c,PlayerWidget.class)));}
}
